/**
 * 图片字符识别：纯函数，全程本地（内置 5x7 点阵模板匹配，无外部 OCR）。
 * 流程：灰度 -> 暗阈值二值化 -> 连通域去噪 -> 列投影分割 -> 归一化 5x7 -> 模板匹配。
 * 置信度 = 最优与次优模板的间隔；低于阈值输出 skip，不硬猜。
 */
import { toGray } from './image.js';
import { FONT, CHARSET } from './font.js';

export const CHAR_DEFAULTS = { confidenceThreshold: 0.3, minComponentWidth: 2 };

/** 连通域标记（8 邻域）。 */
function connectedComponents(bits, width, height) {
  const labels = new Int32Array(width * height).fill(-1);
  const sizes = [];
  const stack = [];
  for (let i = 0; i < bits.length; i++) {
    if (!bits[i] || labels[i] >= 0) continue;
    const id = sizes.length;
    let size = 0;
    stack.push(i);
    labels[i] = id;
    while (stack.length) {
      const p = stack.pop();
      size++;
      const px = p % width, py = (p / width) | 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const nx = px + dx, ny = py + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const ni = ny * width + nx;
        if (bits[ni] && labels[ni] < 0) { labels[ni] = id; stack.push(ni); }
      }
    }
    sizes.push(size);
  }
  return { labels, sizes };
}

/** 字符笔画为暗色：固定暗阈值 + 去除微小连通域（噪点）。 */
function extractGlyphBits(gray, width, height) {
  const bits = new Uint8Array(width * height);
  for (let i = 0; i < gray.length; i++) bits[i] = gray[i] < 110 ? 1 : 0;
  const { labels, sizes } = connectedComponents(bits, width, height);
  const keep = sizes.map(s => s >= 12);
  const out = new Uint8Array(width * height);
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] && labels[i] >= 0 && keep[labels[i]]) out[i] = 1;
  }
  return out;
}

/** 把任意二值区域重采样为 5x7 网格（块占用率 > 0.25 记 1）。 */
function normalizeTo5x7(bits, width, x0, y0, w, h) {
  const grid = new Array(7).fill(0).map(() => new Array(5).fill(0));
  for (let gy = 0; gy < 7; gy++) {
    for (let gx = 0; gx < 5; gx++) {
      const sx0 = Math.floor(x0 + (gx * w) / 5), sx1 = Math.max(sx0 + 1, Math.floor(x0 + ((gx + 1) * w) / 5));
      const sy0 = Math.floor(y0 + (gy * h) / 7), sy1 = Math.max(sy0 + 1, Math.floor(y0 + ((gy + 1) * h) / 7));
      let on = 0, tot = 0;
      for (let y = sy0; y < sy1; y++) for (let x = sx0; x < sx1; x++) { tot++; if (bits[y * width + x]) on++; }
      grid[gy][gx] = on / tot > 0.25 ? 1 : 0;
    }
  }
  return grid;
}

function hammingToFont(grid) {
  const scores = [];
  for (const ch of CHARSET) {
    const rows = FONT[ch];
    let dist = 0;
    for (let y = 0; y < 7; y++) for (let x = 0; x < 5; x++) {
      if (grid[y][x] !== (rows[y][x] === '1' ? 1 : 0)) dist++;
    }
    scores.push({ ch, dist });
  }
  scores.sort((a, b) => a.dist - b.dist);
  return scores;
}

/** 列投影分割字符区域。 */
function segment(bits, width, height, minW) {
  const colInk = new Array(width).fill(0);
  for (let x = 0; x < width; x++) for (let y = 0; y < height; y++) colInk[x] += bits[y * width + x];
  const segs = [];
  let start = -1, gap = 0;
  for (let x = 0; x < width; x++) {
    if (colInk[x] > 0) {
      if (start < 0) start = x;
      gap = 0;
    } else if (start >= 0) {
      gap++;
      if (gap >= 2) { // 连续 2 列空白视为字符间隔
        if (x - gap - start + 1 >= minW) segs.push([start, x - gap]);
        start = -1;
      }
    }
  }
  if (start >= 0 && width - start >= minW) segs.push([start, width - 1]);
  return segs.map(([x0, x1]) => {
    let y0 = height, y1 = 0;
    for (let x = x0; x <= x1; x++) for (let y = 0; y < height; y++) {
      if (bits[y * width + x]) { if (y < y0) y0 = y; if (y > y1) y1 = y; }
    }
    return { x0, x1, y0, y1 };
  });
}

export function recognizeChars(img, options = {}) {
  const opts = { ...CHAR_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);
  const bits = extractGlyphBits(gray, width, height);
  const regions = segment(bits, width, height, opts.minComponentWidth);
  if (regions.length === 0) return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };

  const chars = [];
  let minConf = 1;
  for (const r of regions) {
    const grid = normalizeTo5x7(bits, width, r.x0, r.y0, r.x1 - r.x0 + 1, r.y1 - r.y0 + 1);
    const scores = hammingToFont(grid);
    const best = scores[0], second = scores[1];
    // 置信度：最优与次优的距离间隔，相对 35 个像素归一化
    const conf = Math.max(0, (second.dist - best.dist) / Math.max(1, second.dist));
    chars.push({ ch: best.ch, confidence: conf, distance: best.dist });
    if (conf < minConf) minConf = conf;
  }
  const text = chars.map(c => c.ch).join('');
  if (minConf < opts.confidenceThreshold) {
    return { action: 'skip', reason: 'low-confidence', confidence: minConf, text, chars };
  }
  return { action: 'solve', text, confidence: minConf, chars };
}
/**
 * 内置 5x7 点阵字体（A-Z 0-9 子集）：本地小模型，识别与 fixture 生成共用，
 * 保证全程本地、零外部 OCR 依赖。
 */
