import { test } from 'node:test';
import assert from 'node:assert/strict';
import { recognizeChars } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

const MIN_ACCURACY = 0.9;

test('字符识别：fixture 准确率 ≥ 90%（全程本地模板匹配）', () => {
  const man = loadManifest();
  let correct = 0, wrong = 0;
  const errors = [];
  for (const entry of man.chars) {
    const r = recognizeChars(loadRaw('chars', entry));
    if (r.action === 'solve' && r.text === entry.text) correct++;
    else if (r.action === 'solve') { wrong++; errors.push({ file: entry.file, expected: entry.text, got: r.text }); }
    // action === 'skip'：允许跳过，不计入错误
  }
  const acc = correct / man.chars.length;
  assert.equal(wrong, 0, `存在硬猜错误: ${JSON.stringify(errors)}`);
  assert.ok(acc >= MIN_ACCURACY, `准确率 ${(acc * 100).toFixed(1)}% < ${MIN_ACCURACY * 100}%`);
});

test('字符识别：空白图输出 skip', () => {
  const img = { width: 120, height: 50, data: new Uint8ClampedArray(120 * 50 * 4).fill(245) };
  const r = recognizeChars(img);
  assert.equal(r.action, 'skip');
});

test('字符识别：纯噪点图低置信度时 skip 而非硬猜', () => {
  const img = { width: 120, height: 50, data: new Uint8ClampedArray(120 * 50 * 4) };
  let seed = 42;
  for (let i = 0; i < img.data.length; i += 4) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const v = seed % 256;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
    img.data[i + 3] = 255;
  }
  const r = recognizeChars(img);
  if (r.action === 'solve') {
    assert.ok(r.confidence >= 0.3, '低置信度不应输出 solve');
  }
});
