import { test } from 'node:test';
import assert from 'node:assert/strict';
import { locateGap } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

const ERROR_TOLERANCE_PX = 3;
const MIN_SUCCESS_RATE = 0.95;

test('缺口定位：误差 ≤ 3px 且成功率 ≥ 95%（噪点/渐变/伪缺口干扰下）', () => {
  const man = loadManifest();
  let solved = 0;
  const failures = [];
  for (const entry of man.slider) {
    const r = locateGap(loadRaw('slider', entry));
    if (r.action === 'solve' && Math.abs(r.x - entry.gapX) <= ERROR_TOLERANCE_PX) {
      solved++;
    } else {
      failures.push({ file: entry.file, expected: entry.gapX, got: r.x, action: r.action });
    }
  }
  const rate = solved / man.slider.length;
  assert.ok(rate >= MIN_SUCCESS_RATE,
    `成功率 ${(rate * 100).toFixed(1)}% < ${MIN_SUCCESS_RATE * 100}%，失败: ${JSON.stringify(failures)}`);
});

test('缺口定位：无边缘的纯色图应输出 skip 而非硬猜', () => {
  const img = { width: 100, height: 60, data: new Uint8ClampedArray(100 * 60 * 4).fill(128) };
  const r = locateGap(img);
  assert.equal(r.action, 'skip');
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generateTrajectory, trajectoryStats } from '../core/index.js';

test('轨迹：终点精确到达目标距离', () => {
  for (const d of [80, 137, 210]) {
    const s = trajectoryStats(generateTrajectory(d, { seed: 7 }));
    assert.equal(s.endX, d);
  }
});

test('轨迹：时长随距离增长且落在拟人区间', () => {
  const t1 = trajectoryStats(generateTrajectory(60, { seed: 1 })).duration;
  const t2 = trajectoryStats(generateTrajectory(200, { seed: 1 })).duration;
  assert.ok(t2 > t1, `距离更远应更慢: ${t1} vs ${t2}`);
  assert.ok(t1 >= 300 && t2 <= 2500, `时长应在拟人区间: ${t1}, ${t2}`);
});

test('轨迹：速度曲线先升后降（峰值在中段），起止速度低于峰值', () => {
  const s = trajectoryStats(generateTrajectory(150, { seed: 3 }));
  assert.ok(s.maxSpeedAt > 0.15 && s.maxSpeedAt < 0.9, `速度峰值时刻 ${s.maxSpeedAt} 应在中段`);
  assert.ok(s.startSpeed < s.maxSpeed, '起步速度应低于峰值');
  assert.ok(s.endSpeed < s.maxSpeed, '末端速度应低于峰值');
});

test('轨迹：存在过冲 + 回拉，且含垂直抖动', () => {
  const s = trajectoryStats(generateTrajectory(150, { seed: 5 }));
  assert.ok(s.hasOvershoot, '应有末端过冲（随后回拉）');
  assert.ok(s.yJitter > 0.3, '应有垂直随机抖动');
});

test('轨迹：相同 seed 可复现（确定性，便于断言）', () => {
  const a = generateTrajectory(120, { seed: 99 });
  const b = generateTrajectory(120, { seed: 99 });
  assert.deepEqual(a, b);
});
