/**
 * 滑块缺口定位 v2（纯函数，全程本地）：
 * 软边缘/高斯模糊缺口 -> 左右两侧均为「亮->暗 变暗边缘」（真缺口暗于背景，
 * 左右缘方向相反但都是变暗过渡），配合暗化填充、几何成对与上下边缘，
 * 抗渐变背景 / 纹理 / 伪缺口 / 噪点。
 * 位置用边缘列能量在峰值附近的重心（亚像素）估计，精度到 0.x px。
 */
import { toGray } from './image.js';

export const SLIDER_DEFAULTS = {
  minGapWidth: 30,
  maxGapWidth: 68,
  minX: 60,
  confidenceThreshold: 0.45,
};

function convolve(arr, kernel, width, height, horizontal) {
  const r = (kernel.length - 1) >> 1;
  const out = new Float64Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let s = 0;
      for (let k = -r; k <= r; k++) {
        const xx = horizontal ? x + k : x;
        const yy = horizontal ? y : y + k;
        if (xx < 0 || yy < 0 || xx >= width || yy >= height) continue;
        s += arr[yy * width + xx] * kernel[k + r];
      }
      out[y * width + x] = s;
    }
  }
  return out;
}

/** 变暗边缘能量：左缘 darkEdge<0（亮到暗），右缘 darkEdge>0（暗到亮）。 */
function edgeProfiles(gray, width, height) {
  const k = [0.055, 0.18, 0.3, 0, -0.3, -0.18, -0.055]; // DoG 风格单边 7 抽头
  const g = convolve(gray, k, width, height, true);
  const y0 = Math.floor(height * 0.14), y1 = Math.ceil(height * 0.86);
  const rows = y1 - y0;
  const darkL = new Float64Array(width); // 亮->暗强度（取负方向）
  const darkR = new Float64Array(width); // 暗->亮强度
  for (let x = 0; x < width; x++) {
    let sl = 0, sr = 0;
    for (let y = y0; y < y1; y++) {
      const v = g[y * width + x];
      if (v < 0) sl += -v; else sr += v;
    }
    darkL[x] = sl / rows;
    darkR[x] = sr / rows;
  }
  return { darkL, darkR, y0, y1 };
}

function smooth(a) {
  const out = new Float64Array(a.length);
  for (let i = 1; i < a.length - 1; i++) out[i] = (a[i - 1] + 2 * a[i] + a[i + 1]) / 4;
  out[0] = a[0]; out[a.length - 1] = a[a.length - 1];
  return out;
}

/** 能量峰集合：局部极大且超过自适应阈值，记录峰顶与亚像素重心。 */
function findPeaks(e, threshold) {
  const peaks = [];
  for (let x = 2; x < e.length - 2; x++) {
    if (e[x] < threshold) continue;
    if (!(e[x] >= e[x - 1] && e[x] >= e[x + 1] && e[x] >= e[x - 2] && e[x] >= e[x + 2])) continue;
    // 亚像素重心：在峰周围 3 列内按能量加权
    let num = 0, den = 0;
    for (let dx = -2; dx <= 2; dx++) {
      const w = Math.max(0, e[x + dx] - threshold * 0.5);
      num += (x + dx) * w; den += w;
    }
    peaks.push({ x, sx: den > 0 ? num / den : x, e: e[x] });
  }
  return peaks;
}

export function locateGap(img, options = {}) {
  const opts = { ...SLIDER_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);
  const { darkL, darkR, y0, y1 } = edgeProfiles(gray, width, height);
  const el = smooth(darkL), er = smooth(darkR);

  // 自适应阈值：取边缘能量的高分位数，避免渐变整体抬升造成误判
  const sorted = Float64Array.from([...el, ...er]).sort();
  const q = (p) => sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))];
  const noise = q(0.5);
  const thrL = Math.max(q(0.92), noise * 2.4);
  const thrR = thrL;

  const leftPeaks = findPeaks(el, thrL);
  const rightPeaks = findPeaks(er, thrR);

  // 候选：左缘 + 间距合规的右缘，要求两缘强度接近且都明显
  let best = null;
  for (const lp of leftPeaks) {
    if (lp.x < opts.minX) continue;
    for (const rp of rightPeaks) {
      const w = rp.sx - lp.sx;
      if (w < opts.minGapWidth || w > opts.maxGapWidth) continue;
      const balance = Math.min(lp.e, rp.e) / Math.max(lp.e, rp.e); // 成对边缘应强度均衡
      if (balance < 0.45) continue;
      const score = (lp.e + rp.e) * balance;
      if (!best || score > best.score) best = { lp, rp, w, score };
    }
  }
  if (!best) return { action: 'skip', reason: 'no-gap-pair', confidence: 0 };

  // 内部暗化验证：缺口内部相对两侧外部应更暗
  const interiorDarkness = (() => {
    const ix0 = Math.round(best.lp.sx + 4), ix1 = Math.round(best.rp.sx - 4);
    let inside = 0, ci = 0, outside = 0, co = 0;
    for (let y = y0; y < y1; y++) {
      for (let x = ix0; x < ix1; x++) { inside += gray[y * width + x]; ci++; }
      for (let x = Math.max(2, Math.round(best.lp.sx) - 14); x < Math.max(3, Math.round(best.lp.sx) - 4); x++) {
        outside += gray[y * width + x]; co++;
      }
    }
    return co ? outside / co - inside / ci : 0;
