  // 用响应的稳健尺度（MAD）设阈值
  const absd = Float64Array.from(d).map(Math.abs).sort();
  const med = absd[Math.floor(absd.length * 0.5)];
  const scale = med * 2.2; // 背景渐变/纹理下的典型响应尺度

  let best = null;
