    for (let w = opts.minGapWidth; w <= opts.maxGapWidth; w++) {
      const rxi = Math.round(left.sx + w);
      if (rxi < 2 || rxi >= width - 2) continue;
      if (d[rxi] <= scale * 0.5) continue;
      const right = edgeCentroid(d, rxi, +1);
      const realW = right.sx - left.sx;
      if (realW < opts.minGapWidth || realW > opts.maxGapWidth) continue;
      const balance = Math.min(left.mag, right.mag) / Math.max(left.mag, right.mag);
      if (balance < 0.5) continue;
      const score = (left.mag + right.mag) * balance;
      if (!best || score > best.score) best = { left, right, w: realW, score };
    }
  }
