  // 4) 内部暗化：缺口中部应比外部（左缘左侧）明显更暗
  const cx = Math.round((best.left.sx + best.right.sx) / 2);
  const outside = (sm[Math.max(2, Math.round(best.left.sx) - 12)] +
                   sm[Math.max(1, Math.round(best.left.sx) - 7)]) / 2;
  const inside = sm[cx];
  const darkness = outside - inside;
  if (darkness < 4) return { action: 'skip', reason: 'not-dark', confidence: 0.1 };

