  const edgeStrength = Math.min(1, ((best.left.mag + best.right.mag) / 2) / (scale * 2.4));
  const balance = Math.min(best.left.mag, best.right.mag) / Math.max(best.left.mag, best.right.mag);
  const darkConf = Math.min(1, darkness / 30);
  const confidence = Math.round(
    Math.max(0, Math.min(1, 0.4 * edgeStrength + 0.3 * balance + 0.3 * darkConf)) * 1000) / 1000;

  const result = {
    x: Math.round(best.left.sx * 100) / 100,
    rightX: Math.round(best.right.sx * 100) / 100,
    gapWidth: Math.round(best.w * 100) / 100,
    confidence,
  };
  if (confidence < opts.confidenceThreshold) return { action: 'skip', reason: 'low-confidence', ...result };
  return { action: 'solve', ...result };
}
