/**
 * 滑块缺口定位 v2（纯函数，全程本地）。
 * 针对高斯模糊软边缘暗缺口：
 *  列均值（垂直条带平均掉纹理/噪点）-> 多尺度(σ∈{1.2,2.2,3.2,4.2})高斯差分 ->
 *  每个尺度提取「亮→暗(负)/暗→亮(正)」边缘响应 -> 按缺口宽度先验配缘 ->
 *  以响应剖面过零点线性插值做亚像素定位，多尺度中取得分最高者 ->
 *  内部暗化 + 边缘成对强度经逻辑斯蒂标定给出置信度。
 */
import { toGray } from './image.js';

export const SLIDER_DEFAULTS = {
  minGapWidth: 30,
  maxGapWidth: 68,
  minX: 60,
  confidenceThreshold: 0.45,
};
const SIGMAS = [1.2, 2.2, 3.2, 4.2];

function gaussianSmooth(a, sigma) {
  const rad = Math.max(2, Math.ceil(sigma * 2.4));
  const out = new Float64Array(a.length);
  for (let x = 0; x < a.length; x++) {
    let s = 0, z = 0;
    for (let k = -rad; k <= rad; k++) {
      const xx = x + k;
      if (xx < 0 || xx >= a.length) continue;
      const w = Math.exp(-(k * k) / (2 * sigma * sigma));
      s += a[xx] * w; z += w;
    }
    out[x] = s / z;
  }
  return out;
}

/** 沿剖面求边缘（极值簇）的零交叉式亚像素位置：
 *  取极值两侧响应衰减到峰值一半的两点，插值「半峰值」位置。 */
function edgeLocation(d, center, sign) {
  const half = sign * d[center] * 0.5;
  let lo = center, hi = center;
  for (let x = center; x >= 1 && sign * d[x] > half; x--) lo = x - 1;
  for (let x = center; x < d.length - 1 && sign * d[x] > half; x++) hi = x + 1;
  const interp = (a, b) => {
    const va = sign * d[a] - sign * half;
    const vb = sign * d[b] - sign * half;
    if (va === vb) return a;
    return a + (0 - va) / (vb - va) * (b - a);
  };
  const xl = interp(lo, lo + 1), xr = interp(hi - 1, hi);
  return { sx: (xl + xr) / 2, mag: Math.abs(d[center]) };
}

function detectAtScale(sm, width, opts) {
  const d = new Float64Array(width);
  for (let x = 1; x < width - 1; x++) d[x] = (sm[x + 1] - sm[x - 1]) / 2;

  const absd = Float64Array.from(d).map(Math.abs).sort();
  const scale = absd[Math.floor(absd.length * 0.5)] * 2.2;

  const minima = [], maxima = [];
  for (let x = opts.minX - 3; x < width - 2; x++) {
    if (d[x] < -scale && d[x] <= d[x - 1] && d[x] <= d[x + 1]) minima.push(edgeLocation(d, x, -1));
    if (d[x] > scale * 0.5 && d[x] >= d[x - 1] && d[x] >= d[x + 1]) maxima.push(edgeLocation(d, x, +1));
  }
  let best = null;
  for (const left of minima) {
    if (left.sx < opts.minX) continue;
    for (const right of maxima) {
      const w = right.sx - left.sx;
      if (w < opts.minGapWidth || w > opts.maxGapWidth) continue;
      const balance = Math.min(left.mag, right.mag) / Math.max(left.mag, right.mag);
      if (balance < 0.5) continue;
      const score = (left.mag + right.mag) * balance;
      if (!best || score > best.score) best = { left, right, w, score, scale, sm };
    }
  }
  return best;
}

export function locateGap(img, options = {}) {
  const opts = { ...SLIDER_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);

  const y0 = Math.floor(height * 0.1), y1 = Math.ceil(height * 0.9);
  const col = new Float64Array(width);
  for (let x = 0; x < width; x++) {
    let s = 0;
    for (let y = y0; y < y1; y++) s += gray[y * width + x];
    col[x] = s / (y1 - y0);
  }

  let best = null;
  for (const sigma of SIGMAS) {
    const cand = detectAtScale(gaussianSmooth(col, sigma), width, opts);
    if (cand && (!best || cand.score > best.score)) best = cand;
  }
  if (!best) return { action: 'skip', reason: 'no-gap-pair', confidence: 0 };

