import { toGray } from './image.js';
import { TEMPLATES, TEMPLATE_CHARS, TEMPLATE_GRID } from './templates.js';

export const CHAR_DEFAULTS = { confidenceThreshold: 0.5, expectedLength: null };
const [GW, GH] = TEMPLATE_GRID;

function localBackground(gray, width, height, radius) {
  const tmp = new Float32Array(width * height);
  const out = new Float32Array(width * height);
  for (let y = 0; y < height; y++) {
    let s = 0;
    for (let x = 0; x < Math.min(width, radius); x++) s += gray[y * width + x];
    for (let x = 0; x < width; x++) {
      const xa = Math.max(0, x - radius), xb = Math.min(width - 1, x + radius);
      if (x + radius < width) s += gray[y * width + x + radius];
      if (x - radius - 1 >= 0) s -= gray[y * width + x - radius - 1];
      tmp[y * width + x] = s / (xb - xa + 1);
    }
  }
  for (let x = 0; x < width; x++) {
    let s = 0;
    for (let y = 0; y < Math.min(height, radius); y++) s += tmp[y * width + x];
    for (let y = 0; y < height; y++) {
      const ya = Math.max(0, y - radius), yb = Math.min(height - 1, y + radius);
      if (y + radius < height) s += tmp[(y + radius) * width + x];
      if (y - radius - 1 >= 0) s -= tmp[(y - radius - 1) * width + x];
      out[y * width + x] = s / (yb - ya + 1);
    }
  }
  return out;
}

function erode(b, w, h) {
  const o = new Uint8Array(w * h);
  for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) {
    const i = y * w + x;
    o[i] = b[i] && b[i - 1] && b[i + 1] && b[i - w] && b[i + w] ? 1 : 0;
  }
  return o;
}
function dilate(b, w, h) {
  const o = new Uint8Array(w * h);
  for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) {
    const i = y * w + x;
    o[i] = (b[i] || b[i - 1] || b[i + 1] || b[i - w] || b[i + w]) ? 1 : 0;
  }
  return o;
}

function removeHorizontalBars(bits, w, h) {
  const out = new Uint8Array(bits);
  for (let y = 0; y < h; y++) {
    let run = 0;
    for (let x = 0; x <= w; x++) {
      if (x < w && bits[y * w + x]) { run++; continue; }
      if (run > w * 0.28) for (let xx = x - run; xx < x; xx++) out[y * w + xx] = 0;
      run = 0;
    }
  }
  return out;
}

function filterComponents(bits, w, h) {
  const labels = new Int32Array(w * h).fill(-1);
  const comps = [];
  const stack = [];
  for (let i = 0; i < bits.length; i++) {
    if (!bits[i] || labels[i] >= 0) continue;
    const id = comps.length;
    let minX = w, maxX = 0, minY = h, maxY = 0, size = 0;
    stack.push(i); labels[i] = id;
    while (stack.length) {
      const p = stack.pop(); size++;
      const px = p % w, py = (p / w) | 0;
      if (px < minX) minX = px; if (px > maxX) maxX = px;
      if (py < minY) minY = py; if (py > maxY) maxY = py;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const nx = px + dx, ny = py + dy;
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        const ni = ny * w + nx;
        if (bits[ni] && labels[ni] < 0) { labels[ni] = id; stack.push(ni); }
