    if (cw > w * 0.3 || chh > h * 0.95) return false;
    if (cw / chh > 6 || chh / cw > 12) return false;
    return true;
  });
  const o = new Uint8Array(w * h);
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] && labels[i] >= 0 && keep[labels[i]]) o[i] = 1;
  }
  return o;
