  const bg = localBackground(gray, w, h, 9);
  let bits = new Uint8Array(w * h);
  for (let i = 0; i < bits.length; i++) bits[i] = bg[i] - gray[i] > 22 ? 1 : 0;
  bits = dilate(erode(bits, w, h), w, h);
  bits = removeHorizontalBars(bits, w, h);
  bits = filterComponents(bits, w, h);
  return bits;
