function gridRegions(bits, w, h, xStart, xEnd, n) {
  const span = xEnd - xStart + 1;
  const step = span / n;
  const overlap = Math.max(0, Math.round(step * 0.12)); // 每侧吞 12% 应对粘连/旋转
  const regions = [];
  for (let k = 0; k < n; k++) {
    const gx0 = Math.round(xStart + k * step);
    const gx1 = Math.round(xStart + (k + 1) * step) - 1;
    const rx0 = Math.max(0, gx0 - (k > 0 ? overlap : 0));
    const rx1 = Math.min(w - 1, gx1 + (k < n - 1 ? overlap : 0));
    let y0 = h, y1 = 0, ink = 0;
    for (let y = 0; y < h; y++) for (let x = rx0; x <= rx1; x++) {
      if (bits[y * w + x]) { if (y < y0) y0 = y; if (y > y1) y1 = y; ink++; }
    }
    regions.push({ x0: rx0, x1: rx1, y0: y0 === h ? 0 : y0, y1: y1 === 0 ? h - 1 : y1, ink });
  }
  return regions;
}

/* ---------- 模板匹配 ---------- */

function coverageGrid(bits, w, r) {
  const rw = r.x1 - r.x0 + 1, rh = r.y1 - r.y0 + 1;
  const grid = new Array(GH * GW);
  let gi = 0;
  for (let gy = 0; gy < GH; gy++) {
    for (let gx = 0; gx < GW; gx++) {
      const sx0 = r.x0 + Math.floor(gx * rw / GW);
      const sx1 = Math.max(sx0 + 1, r.x0 + Math.floor((gx + 1) * rw / GW));
      const sy0 = r.y0 + Math.floor(gy * rh / GH);
      const sy1 = Math.max(sy0 + 1, r.y0 + Math.floor((gy + 1) * rh / GH));
      let on = 0, tot = 0;
      for (let y = sy0; y < sy1; y++) for (let x = sx0; x < sx1; x++) {
        tot++; if (bits[y * w + x]) on++;
      }
      grid[gi++] = on / tot;
    }
  }
  return grid;
}

const T = TEMPLATE_CHARS.map((ch) => {
  const v = TEMPLATES[ch].flat();
  const mean = v.reduce((a, b) => a + b, 0) / v.length;
  const z = v.map(x => x - mean);
  return { ch, z, norm: Math.sqrt(z.reduce((a, b) => a + b * b, 0)) };
});

function matchChar(grid) {
  const mean = grid.reduce((a, b) => a + b, 0) / grid.length;
  const z = grid.map(x => x - mean);
  const norm = Math.sqrt(z.reduce((a, b) => a + b * b, 0));
  const scores = [];
  if (norm < 1e-6) return TEMPLATE_CHARS.map(ch => ({ ch, ncc: -1 }));
  for (const t of T) {
    let dot = 0;
    for (let i = 0; i < z.length; i++) dot += z[i] * t.z[i];
    scores.push({ ch: t.ch, ncc: dot / (norm * t.norm) });
  }
  scores.sort((a, b) => b.ncc - a.ncc);
  return scores;
}

function charProb(margin, ncc) {
  const z = -3.4 + 9.0 * margin + 2.0 * Math.max(-0.2, Math.min(1, ncc));
  return 1 / (1 + Math.exp(-z));
}

export function recognizeChars(img, options = {}) {
  const opts = { ...CHAR_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);
  const bits = preprocess(gray, width, height);
  const bounds = inkBounds(bits, width, height);
  if (!bounds) return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };

  const lengthCandidates = opts.expectedLength ? [opts.expectedLength] : [4, 5, 6];
  let bestPlan = null;
  for (const n of lengthCandidates) {
    const regions = gridRegions(bits, width, height, bounds.x0, bounds.x1, n);
    const charResults = [];
    let planScore = 0, minProb = 1, empty = 0;
    for (const r of regions) {
      if (r.ink < 10) empty++;
      const scores = matchChar(coverageGrid(bits, width, r));
      const best = scores[0], second = scores[1];
      const margin = Math.max(0, best.ncc - second.ncc);
      const prob = charProb(margin, best.ncc);
      charResults.push({ r, best, second, margin, prob });
      planScore += prob;
      if (prob < minProb) minProb = prob;
    }
    if (empty) continue; // 某格几乎无墨 -> 长度选错
    const plan = { n, regions: charResults, score: planScore, minProb };
    if (!bestPlan || plan.score > bestPlan.score) bestPlan = plan;
  }
  if (!bestPlan) return { action: 'skip', reason: 'segmentation', confidence: 0, text: '' };

  const chars = bestPlan.regions.map(c => ({
    ch: c.best.ch,
    confidence: Math.round(c.prob * 1000) / 1000,
    ncc: Math.round(c.best.ncc * 1000) / 1000,
    margin: Math.round(c.margin * 1000) / 1000,
    runnerUp: c.second.ch,
  }));
  const text = chars.map(c => c.ch).join('');
  const confidence = Math.round(bestPlan.minProb * 1000) / 1000;
  if (confidence < opts.confidenceThreshold) {
    return { action: 'skip', reason: 'low-confidence', confidence, text, chars };
  }
  return { action: 'solve', text, confidence, chars, length: bestPlan.n };
}
