// synthetic pipeline sanity: crop template 'd' grid -> NCC self should be 1; simulate scaled 28x40 glyph from grid
import { TEMPLATES, TEMPLATE_CHARS } from './core/templates.js';
function resample(grid, rw, rh){
 const GW=8,GH=10,out=[];
 for(let gy=0;gy<rh;gy++){for(let gx=0;gx<rw;gx++){
  const sx=Math.min(7,Math.floor(gx/rw*GW)),sy=Math.min(9,Math.floor(gy/rh*GH));
  out.push(grid[sy][sx]);}}
 return out;}
function grid8x10(bits,rw,rh){const g=[];
 for(let gy=0;gy<10;gy++){const row=[];for(let gx=0;gx<8;gx++){
 const sx0=Math.floor(gx*rw/8),sx1=Math.max(sx0+1,Math.floor((gx+1)*rw/8));
