function glyphBand(bits, w, h, rx0, rx1) {
  const row = new Float64Array(h);
  let total = 0;
  for (let y = 0; y < h; y++) {
    let c = 0;
    for (let x = rx0; x <= rx1; x++) c += bits[y * w + x];
    row[y] = c; total += c;
