  if (total < 10) return { y0: 0, y1: h - 1, ink: total };
  const sm = new Float64Array(h);
  for (let y = 0; y < h; y++) {
    sm[y] = (row[Math.max(0, y - 1)] + row[y] + row[Math.min(h - 1, y + 1)]) / 3;
  }
  const active = Float64Array.from(sm).filter(v => v > 0.5).sort((a, b) => a - b);
  const mean = active.length ? active.reduce((a, b) => a + b, 0) / active.length : 1;
  const on = sm.map(v => v > mean * 0.22);
  let y0 = -1, y1 = -1;
  for (let y = 0; y < h; y++) if (on[y]) {
