    const c = (y0 + y1) / 2;
    y0 = Math.max(0, Math.round(c - minH / 2));
    y1 = Math.min(h - 1, Math.round(c + minH / 2));
  }
  let ink = 0;
  for (let y = y0; y <= y1; y++) ink += row[y];
  return { y0, y1, ink };
}

