p="core/chars.js"
s=open(p).read()
import re
start=s.index("/** 在候选 x 区间内求字形 y 范围")
end=s.index("/** 等宽网格切 n 格")
new='''/** 字形 y 范围：行墨点 / 区间宽度 = 行覆盖率；取覆盖率超过
 *  「所有非零行覆盖率中位数」35% 的连续主行带（允许中间 1~2 行凹陷，
 *  即孔洞），再对结果做最小字高保护（旋转大字不小于图高 34%）。 */
function glyphBand(bits, w, h, rx0, rx1) {
  const rw = rx1 - rx0 + 1;
  const cov = new Float64Array(h);
  let total = 0;
  for (let y = 0; y < h; y++) {
    let c = 0;
    for (let x = rx0; x <= rx1; x++) c += bits[y * w + x];
    cov[y] = c / rw; total += c;
  }
  if (total < 10) return { y0: 0, y1: h - 1, ink: total };
  const sm = new Float64Array(h);
  for (let y = 0; y < h; y++) {
    sm[y] = (cov[Math.max(0, y - 1)] + cov[y] + cov[Math.min(h - 1, y + 1)]) / 3;
  }
  const nonzero = Float64Array.from(sm).filter(v => v > 0.02).sort((a, b) => a - b);
  if (!nonzero.length) return { y0: 0, y1: h - 1, ink: total };
  const med = nonzero[Math.floor(nonzero.length / 2)];
  const onY = [];
  for (let y = 0; y < h; y++) if (sm[y] > med * 0.35) onY.push(y);
  // 主行带 = 覆盖 85% 活跃墨点的最小区间：从活跃行的 7% 分位到 93% 分位
  onY.sort((a, b) => a - b);
  let y0 = onY[Math.floor(onY.length * 0.04)];
  let y1 = onY[Math.min(onY.length - 1, Math.floor(onY.length * 0.96))];
  const minH = Math.round(h * 0.34);
  if (y1 - y0 + 1 < minH) {
    const c = (y0 + y1) / 2;
    const ny0 = Math.max(0, Math.round(c - minH / 2));
    y1 = Math.min(h - 1, ny0 + minH - 1);
    y0 = ny0;
  }
  let ink = 0;
  for (let y = y0; y <= y1; y++) ink += cov[y] * rw;
  return { y0, y1, ink: Math.round(ink) };
}

'''
