/**
 * 置信度校准（离线，在本地 fixture 上运行，无网络）：
 * 读取全部字符 fixture -> 识别得到每字符 {margin,ncc,correct} ->
 * 逻辑斯蒂回归拟合 correct ~ sigmoid(a + b*margin + c*ncc)，
 * 打印经验可靠度分桶与整串阈值表，并输出可粘贴回 core/chars.js 的系数。
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { recognizeChars } from '../core/chars.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const man = JSON.parse(readFileSync(join(ROOT, 'fixtures', 'manifest.json'), 'utf8'));

const load = (dir, e) => ({
  width: e.width, height: e.height,
  data: new Uint8ClampedArray(readFileSync(join(ROOT, 'fixtures', dir, e.raw))),
});

const rows = [];
for (const e of man.chars) {
  const r = recognizeChars(load('chars', e), { expectedLength: e.text.length, confidenceThreshold: 0 });
  if (!r.chars) continue;
  r.chars.forEach((c, k) => rows.push({ margin: c.margin, ncc: c.ncc, y: c.ch === e.text[k] ? 1 : 0 }));
}

// 逻辑斯蒂回归（全批量梯度下降）
let a = -6, b = 6, c = 6;
for (let it = 0; it < 8000; it++) {
  let ga = 0, gb = 0, gc = 0;
  for (const r of rows) {
    const p = 1 / (1 + Math.exp(-(a + b * r.margin + c * r.ncc)));
    const g = p - r.y;
    ga += g; gb += g * r.margin; gc += g * r.ncc;
  }
  const lr = 0.2;
  a -= lr * ga / rows.length; b -= lr * gb / rows.length; c -= lr * gc / rows.length;
}
const prob = (m, n) => 1 / (1 + Math.exp(-(a + b * m + c * n)));

console.log(`samples=${rows.length} per-char acc=${(rows.filter(r => r.y).length / rows.length).toFixed(3)}`);
console.log(`charProb coefficients: a=${a.toFixed(3)} b=${b.toFixed(3)} c=${c.toFixed(3)}`);
console.log('— 预测概率可靠度分桶（应单调且接近桶中值）—');
for (const [lo, hi] of [[0, .2], [.2, .4], [.4, .6], [.6, .8], [.8, .9], [.9, .95], [.95, 1.001]]) {
  const sub = rows.map(r => ({ p: prob(r.margin, r.ncc), y: r.y })).filter(r => r.p >= lo && r.p < hi);
  const emp = sub.length ? sub.filter(r => r.y).length / sub.length : 0;
  console.log(`  p∈[${lo.toFixed(2)},${hi.toFixed(2)})  n=${String(sub.length).padStart(3)}  empirical=${emp.toFixed(3)}`);
}
console.log('— 整串（几何平均）阈值表 —');
for (const diff of ['standard', 'hard', undefined]) {
  const recs = [];
  for (const e of man.chars) {
    if (diff && e.difficulty !== diff) continue;
    const r = recognizeChars(load('chars', e), { expectedLength: e.text.length, confidenceThreshold: 0 });
    if (!r.chars) continue;
    const gm = Math.exp(r.chars.reduce((s, x) => s + Math.log(Math.max(1e-4, x.confidence)), 0) / r.chars.length);
    recs.push({ p: gm, ok: r.text === e.text, difficulty: e.difficulty });
  }
  for (const t of [0.7, 0.8, 0.86, 0.9]) {
    const sol = recs.filter(r => r.p >= t);
    const corr = sol.filter(r => r.ok).length;
    console.log(`  ${diff ?? 'all'} t=${t}: solve=${sol.length} correct=${corr} wrong=${sol.length - corr} ` +
      `precision=${(corr / Math.max(1, sol.length)).toFixed(2)} coverage=${(sol.length / recs.length).toFixed(2)}`);
  }
}
EOF
