import { test } from 'node:test';
import assert from 'node:assert/strict';
import { recognizeChars } from '../core/index.js';
import { TEMPLATE_CHARS } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

test('字符：字符集覆盖大小写字母 + 数字共 62 类', () => {
  assert.equal(TEMPLATE_CHARS.length, 62);
  for (const ch of ['0', '9', 'A', 'Z', 'a', 'z']) assert.ok(TEMPLATE_CHARS.includes(ch));
});

test('字符：所有 solve 输出必须与真值完全一致（0 硬猜错误，低于阈值必须 skip）', () => {
  const man = loadManifest();
  let solved = 0;
  const hardErrors = [];
  for (const entry of man.chars) {
    const r = recognizeChars(loadRaw('chars', entry), { expectedLength: entry.text.length });
    if (r.action === 'solve') {
      solved++;
      if (r.text !== entry.text) hardErrors.push({ file: entry.file, expected: entry.text, got: r.text });
    } else {
      assert.equal(r.action, 'skip');
      assert.ok(r.confidence < 0.88, `跳过样本置信度应低于阈值: ${entry.file}`);
    }
  }
  assert.equal(hardErrors.length, 0, `存在硬猜错误: ${JSON.stringify(hardErrors)}`);
  assert.ok(solved >= 5, `高置信度通过样本过少(${solved})，校准不应把可识别样本也跳过`);
});

test('字符：跳过的样本经验正确率应很低（宁漏不错），solve 的正确率为 100%', () => {
  const man = loadManifest();
  let skippedCorrect = 0, skipped = 0, solvedCorrect = 0, solved = 0;
  for (const entry of man.chars) {
    const r = recognizeChars(loadRaw('chars', entry), { expectedLength: entry.text.length });
    if (r.action === 'skip') {
      skipped++;
      // skip 也返回候选文本；若候选恰好全对，属于"被跳过的好样本"，占比必须很低
      if (r.text === entry.text) skippedCorrect++;
    } else {
      solved++;
      if (r.text === entry.text) solvedCorrect++;
    }
  }
  assert.equal(solvedCorrect, solved, '所有 solve 必须正确');
  assert.ok(skippedCorrect / skipped <= 0.2,
    `被跳过样本中其实正确的比例 ${(skippedCorrect / skipped).toFixed(2)} 过高，校准过于保守`);
});

test('字符：空白图 / 纯噪点图输出 skip 而非硬猜', () => {
  const blank = { width: 160, height: 64, data: new Uint8ClampedArray(160 * 64 * 4).fill(245) };
  assert.equal(recognizeChars(blank).action, 'skip');
  const noise = { width: 160, height: 64, data: new Uint8ClampedArray(160 * 64 * 4) };
  let seed = 42;
  for (let i = 0; i < noise.data.length; i += 4) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const v = seed % 256;
    noise.data[i] = noise.data[i + 1] = noise.data[i + 2] = v;
    noise.data[i + 3] = 255;
  }
