test('滑块：缺口亚像素定位，|误差| ≤ 2px（软边缘/渐变/多伪缺口，standard+hard）', () => {
  const man = loadManifest();
  let solved = 0;
  const errors = [];
  const deviations = [];
  for (const entry of man.slider) {
    const r = locateGap(loadRaw('slider', entry));
    assert.ok(['solve', 'skip'].includes(r.action));
    if (r.action === 'solve') {
      solved++;
      const err = Math.abs(r.x - entry.gapX);
      deviations.push(err);
      if (err > 2) errors.push({ file: entry.file, expected: entry.gapX, got: r.x, conf: r.confidence });
    }
  }
  // 高置信度可解样本占比高，且其中无超差
  assert.ok(solved / man.slider.length >= 0.9, `可解率过低: ${solved}/${man.slider.length}`);
  assert.equal(errors.length, 0, `超差样本: ${JSON.stringify(errors)}`);
  const mae = deviations.reduce((a, b) => a + b, 0) / deviations.length;
  assert.ok(mae < 1.2, `平均误差应达亚像素级(<1.2px)，实际 ${mae.toFixed(2)}px`);
});

test('滑块：输出坐标为亚像素（含小数部分，且返回成对右缘/宽度）', () => {
  const man = loadManifest();
  const e = man.slider[0];
  const r = locateGap(loadRaw('slider', e));
  assert.equal(r.action, 'solve');
  assert.ok(typeof r.x === 'number');
  assert.ok(r.rightX > r.x);
  assert.ok(r.gapWidth >= 30 && r.gapWidth <= 68);
  // 至少在整个数据集上出现非整数坐标（证明亚像素估计生效）
  const anyFractional = man.slider.some(en => {
    const rr = locateGap(loadRaw('slider', en));
    return rr.action === 'solve' && Math.abs(rr.x - Math.round(rr.x)) > 1e-6;
  });
  assert.ok(anyFractional, '缺口坐标应包含亚像素（非整数）结果');
});

test('滑块：纯色/无边缘图输出 skip 而非硬猜', () => {
  const img = { width: 120, height: 64, data: new Uint8ClampedArray(120 * 64 * 4).fill(128) };
  assert.equal(locateGap(img).action, 'skip');
});

test('滑块：纯函数确定性', () => {
  const man = loadManifest();
  const e = man.slider[1];
  const img = loadRaw('slider', e);
  assert.deepEqual(locateGap(img), locateGap(img));
});
