import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generateTrajectory, trajectoryStats } from '../core/index.js';

test('轨迹：终点亚像素精确到达目标（浮点坐标）', () => {
  for (const d of [80, 137.5, 210]) {
    const s = trajectoryStats(generateTrajectory(d, { seed: 7 }));
    assert.ok(Math.abs(s.endX - d) < 1e-6, `endX=${s.endX} != ${d}`);
  }
});

test('轨迹：路径含亚像素（非整数）坐标点', () => {
  const t = generateTrajectory(150, { seed: 11 });
  assert.ok(t.points.some(p => Math.abs(p.x - Math.round(p.x)) > 1e-9));
});

test('轨迹：时长随距离增长（类 Fitts）且落在拟人区间', () => {
  const t1 = trajectoryStats(generateTrajectory(60, { seed: 1 })).duration;
  const t2 = trajectoryStats(generateTrajectory(220, { seed: 1 })).duration;
  assert.ok(t2 > t1);
  assert.ok(t1 >= 250 && t2 <= 2600);
});

test('轨迹：速度先升后降（峰值在中段），起止速度低于峰值', () => {
  const s = trajectoryStats(generateTrajectory(160, { seed: 3 }));
  assert.ok(s.maxSpeedAt > 0.15 && s.maxSpeedAt < 0.9);
  assert.ok(s.startSpeed < s.maxSpeed && s.endSpeed < s.maxSpeed);
});

test('轨迹：过冲+回拉、含垂直抖动与微停顿（可统计的拟人特征）', () => {
  const s = trajectoryStats(generateTrajectory(160, { seed: 5 }));
  assert.ok(s.hasOvershoot, '应有末端过冲');
  assert.ok(s.yJitter > 0.3, '应有垂直抖动');
  assert.ok(s.maxSpeed > 0);
});

test('轨迹：统计特征可复现（相同 seed 完全一致）', () => {
  assert.deepEqual(generateTrajectory(120, { seed: 99 }), generateTrajectory(120, { seed: 99 }));
});

test('轨迹：时间单调不减且步长有界（无瞬移）', () => {
  const t = generateTrajectory(180, { seed: 21 });
  for (let i = 1; i < t.points.length; i++) {
    assert.ok(t.points[i].t >= t.points[i - 1].t, '时间单调');
    const dt = Math.max(1, t.points[i].t - t.points[i - 1].t);
    const v = Math.abs(t.points[i].x - t.points[i - 1].x) / dt;
    assert.ok(v < 5, `单步速度异常 ${v}`);
  }
});
