import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';
import { ROOT } from './helpers.js';

// 直接在测试内复算经验可靠度：高置信度字符正确率必须显著高于低置信度字符（校准单调）
test('校准：字符置信度与经验正确率单调一致（高置信度更可靠）', () => {
  const { recognizeChars } = await import('../core/index.js');
  const { loadManifest, loadRaw } = await import('./helpers.js');
  const man = loadManifest();
  const rows = [];
  for (const e of man.chars) {
    const r = recognizeChars(loadRaw('chars', e), { expectedLength: e.text.length, confidenceThreshold: 0 });
    if (!r.chars) continue;
    r.chars.forEach((c, k) => rows.push({ p: c.confidence, ok: c.ch === e.text[k] }));
  }
  const acc = (lo, hi) => {
    const sub = rows.filter(r => r.p >= lo && r.p < hi);
    return sub.length ? sub.filter(r => r.ok).length / sub.length : null;
  };
  const high = acc(0.9, 1.01);
  const low = acc(0, 0.4);
  assert.ok(high !== null && low !== null);
  assert.ok(high >= 0.9, `高置信度字符经验正确率应≥90%: ${high}`);
  assert.ok(low <= 0.25, `低置信度字符经验正确率应≤25%（这批大概率错才该跳过）: ${low}`);
  assert.ok(high > low + 0.4);
});

