(async () => {
  const core = await import(chrome.runtime.getURL('core/index.js'));

  function setStatus(widget, text, ok) {
    let el = widget.querySelector('[data-role="status"]');
    if (!el) {
      el = document.createElement('div');
      el.dataset.role = 'status';
      widget.appendChild(el);
    }
    el.textContent = `[extension] ${text}`;
    el.style.color = ok === undefined ? '#666' : ok ? '#0a0' : '#c00';
  }

  function canvasImage(canvas) {
    const d = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height);
    return { width: d.width, height: d.height, data: d.data };
  }

  function dispatchMouse(el, type, x, y) {
    const rect = el.getBoundingClientRect();
    el.dispatchEvent(new MouseEvent(type, {
      bubbles: true, cancelable: true, view: window,
      clientX: rect.left + x, clientY: rect.top + y,
      button: 0, buttons: type === 'mouseup' ? 0 : 1,
    }));
  }

  const sleep = ms => new Promise(r => setTimeout(r, ms));

  async function solveSlider(widget) {
    const canvas = widget.querySelector('canvas');
    const handle = widget.querySelector('[data-role="handle"]');
    const result = core.locateGap(canvasImage(canvas));
    if (result.action !== 'solve') {
      setStatus(widget, `滑块：低置信度(${(result.confidence ?? 0).toFixed(2)})，跳过/人工`, false);
      return;
    }
    const startX = parseFloat(handle.dataset.x || '0');
    const distance = result.x - startX;                 // 亚像素距离
    const traj = core.generateTrajectory(distance);
    const stats = core.trajectoryStats(traj);
    setStatus(widget, `滑块：缺口 x=${result.x.toFixed(2)} 置信度=${result.confidence.toFixed(2)} ` +
      `${traj.points.length} 步/${stats.duration}ms 过冲=${stats.hasOvershoot}`);
    const y = handle.offsetHeight / 2;
    let prevT = 0;
    dispatchMouse(handle, 'mousedown', startX + 4, y);
    for (const p of traj.points) {
      await sleep(Math.max(3, p.t - prevT));
      prevT = p.t;
      dispatchMouse(document, 'mousemove', startX + p.x, y + p.y);
    }
    dispatchMouse(document, 'mouseup', startX + distance, y);
  }

  function solveChars(widget) {
    const canvas = widget.querySelector('canvas');
    const input = widget.querySelector('input');
    const button = widget.querySelector('button[data-role="verify"]');
    // 页面固定 4 位；真实场景可由 UI 槽位数推断，不给则核心自动在 4~6 间选优
    const result = core.recognizeChars(canvasImage(canvas), { expectedLength: 4 });
    if (result.action !== 'solve') {
      setStatus(widget, `字符：低置信度(${(result.confidence ?? 0).toFixed(2)})，跳过/人工（不硬猜）`, false);
      return;
    }
    input.value = result.text;
    setStatus(widget, `字符：识别为 "${result.text}" 整串置信度=${result.confidence.toFixed(2)}`);
    button.click();
  }

  function scan() {
    document.querySelectorAll('[data-captcha="slider"]').forEach(w => {
      if (!w.dataset.solved) { w.dataset.solved = '1'; solveSlider(w); }
    });
    document.querySelectorAll('[data-captcha="chars"]').forEach(w => {
      if (!w.dataset.solved) { w.dataset.solved = '1'; solveChars(w); }
    });
  }
  scan();
  new MutationObserver(scan).observe(document.body, { childList: true, subtree: true });
})();
